import{_ as a,c as r,o,a9 as t}from"./chunks/framework.Bqk8xQPS.js";const m=JSON.parse('{"title":"Architecture Overview","description":"","frontmatter":{},"headers":[],"relativePath":"api/_media/ARCHITECTURE.md","filePath":"api/_media/ARCHITECTURE.md","lastUpdated":1773933095000}'),i={name:"api/_media/ARCHITECTURE.md"};function n(s,e,d,c,l,h){return o(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="architecture-overview" tabindex="-1">Architecture Overview <a class="header-anchor" href="#architecture-overview" aria-label="Permalink to “Architecture Overview”">​</a></h1><p>The <code>@purista/sandbox</code> package is designed as a decoupled, message-driven component within the PURISTA ecosystem.</p><h2 id="core-components" tabindex="-1">Core Components <a class="header-anchor" href="#core-components" aria-label="Permalink to “Core Components”">​</a></h2><h3 id="_1-sandbox-runtime" tabindex="-1">1. Sandbox Runtime <a class="header-anchor" href="#_1-sandbox-runtime" aria-label="Permalink to “1. Sandbox Runtime”">​</a></h3><p>A standard PURISTA service that exposes commands for sandbox lifecycle management (<code>createSandbox</code>, <code>ensureSandbox</code>, <code>destroySandbox</code>) and execution (<code>executeBash</code>).</p><h3 id="_2-sandbox-drivers" tabindex="-1">2. Sandbox Drivers <a class="header-anchor" href="#_2-sandbox-drivers" aria-label="Permalink to “2. Sandbox Drivers”">​</a></h3><p>The service is driver-agnostic. It interacts with virtualization technologies via a common <code>SandboxDriver</code> interface. This allows the same business logic to run against Docker, Podman, Lima, or Firecracker.</p><h3 id="_3-sandbox-registry" tabindex="-1">3. Sandbox Registry <a class="header-anchor" href="#_3-sandbox-registry" aria-label="Permalink to “3. Sandbox Registry”">​</a></h3><p>A specialized resource that tracks active sandboxes. It uses the PURISTA <strong>State Store</strong> for persistence. Key features include:</p><ul><li><strong>Tenant Isolation</strong>: Ownership is derived from message <code>tenantId</code> + <code>principalId</code> and stored as <code>organizationId</code> + <code>userId</code> plus explicit <code>projectId</code>.</li><li><strong>Self-Healing</strong>: On startup, the service reconciles its internal registry only from runtimes that can recover the full owner tuple from labels/tags.</li></ul><h2 id="message-flow" tabindex="-1">Message Flow <a class="header-anchor" href="#message-flow" aria-label="Permalink to “Message Flow”">​</a></h2><ol><li><strong>Request</strong>: A user or agent sends <code>createSandbox</code> or <code>ensureSandbox</code> with <code>tenantId</code> / <code>principalId</code> in the PURISTA message and <code>projectId</code> in the payload.</li><li><strong>Provisioning</strong>: The service calls <code>driver.createSandbox()</code>.</li><li><strong>Registration</strong>: The new sandbox metadata is stored in the <code>SandboxRegistry</code> (State Store).</li><li><strong>Execution</strong>: AI agents use the <code>executeBash</code> command. The service verifies ownership via the registry before delegating to the driver.</li><li><strong>Teardown</strong>: When a task is finished, <code>destroySandbox</code> is called, cleaning up both the infrastructure and the registry entry.</li></ol><h2 id="lifecycle-rules" tabindex="-1">Lifecycle Rules <a class="header-anchor" href="#lifecycle-rules" aria-label="Permalink to “Lifecycle Rules”">​</a></h2><ul><li><code>createSandbox</code> is explicit and fails with <code>409 Conflict</code> if an owner already has a sandbox.</li><li><code>ensureSandbox</code> is the idempotent path. It returns the current healthy sandbox or recreates an unhealthy one.</li><li>Drivers must not return partial metadata during reconciliation. If owner metadata cannot be recovered, <code>scanRunningSandboxes()</code> must return <code>[]</code> for those instances.</li></ul><h2 id="resource-based-injection" tabindex="-1">Resource-Based Injection <a class="header-anchor" href="#resource-based-injection" aria-label="Permalink to “Resource-Based Injection”">​</a></h2><p>Following the PURISTA v1 patterns, dependencies are injected as resources:</p><ul><li><code>driver</code>: The chosen virtualization implementation.</li><li><code>registry</code>: The state-store-backed registry.</li></ul><p>This ensures that handlers remain pure and easily testable by mocking these resources.</p>',18)])])}const p=a(i,[["render",n]]);export{m as __pageData,p as default};
